USE bandhkam_kamgar_db;
CREATE TABLE IF NOT EXISTS notices (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,title_mr VARCHAR(255) NOT NULL,title_en VARCHAR(255) NULL,description TEXT NOT NULL,category VARCHAR(100) NULL,publish_date DATE NOT NULL,expiry_date DATE NULL,attachment_type ENUM('pdf','image') NULL,attachment_path VARCHAR(500) NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE,is_featured BOOLEAN NOT NULL DEFAULT FALSE,display_order INT NOT NULL DEFAULT 0,created_by BIGINT UNSIGNED NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY idx_notices_public(is_active,publish_date,display_order),CONSTRAINT fk_notices_user FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
